-- Campus Sentinel · PostgreSQL 16 + pgvector 0.8
-- Run once through scripts/migrate.ts. All operational times are timestamptz.
CREATE EXTENSION IF NOT EXISTS vector;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE "user" (
 user_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(120) NOT NULL CHECK(length(trim(name))>0),
 email varchar(254) NOT NULL UNIQUE CHECK(email = lower(email) AND email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'),
 password_hash varchar(255) NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE role (role_id int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, role_name varchar(30) NOT NULL UNIQUE CHECK(role_name IN ('ADMIN','STAFF','REPORTER')), description varchar(255));
CREATE TABLE user_role (user_id uuid REFERENCES "user" ON DELETE CASCADE, role_id int REFERENCES role ON DELETE RESTRICT, assigned_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,role_id));
CREATE TABLE building (building_id int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, building_code varchar(20) NOT NULL UNIQUE, building_name varchar(120) NOT NULL, description varchar(500));
CREATE TABLE location (location_id int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, building_id int NOT NULL REFERENCES building ON DELETE RESTRICT, location_name varchar(120) NOT NULL, floor_number int NOT NULL CHECK(floor_number BETWEEN -10 AND 200), location_type varchar(50) NOT NULL, neo4j_node_id varchar(100) NOT NULL UNIQUE, is_accessible boolean NOT NULL DEFAULT true, UNIQUE(building_id,location_name));
CREATE TABLE incident_category (category_id int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, category_name varchar(80) NOT NULL UNIQUE, base_severity int NOT NULL CHECK(base_severity BETWEEN 1 AND 4), required_skill varchar(80) NOT NULL, is_active boolean NOT NULL DEFAULT true);
CREATE TABLE sla_policy (sla_policy_id int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, category_id int NOT NULL REFERENCES incident_category ON DELETE RESTRICT, severity_level varchar(12) NOT NULL CHECK(severity_level IN ('LOW','MEDIUM','HIGH','CRITICAL')), response_minutes int NOT NULL CHECK(response_minutes>0), resolution_minutes int NOT NULL CHECK(resolution_minutes>=response_minutes), UNIQUE(category_id,severity_level));
CREATE TABLE incident (
 incident_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), location_id int NOT NULL REFERENCES location ON DELETE RESTRICT,
 category_id int NOT NULL REFERENCES incident_category ON DELETE RESTRICT, title varchar(180) NOT NULL CHECK(length(trim(title))>=5), description text NOT NULL CHECK(length(trim(description))>=10),
 severity varchar(12) NOT NULL CHECK(severity IN ('LOW','MEDIUM','HIGH','CRITICAL')), priority_score numeric(8,2) NOT NULL DEFAULT 0 CHECK(priority_score>=0),
 status varchar(20) NOT NULL DEFAULT 'REPORTED' CHECK(status IN ('REPORTED','VERIFIED','ASSIGNED','IN_PROGRESS','RESOLVED','CLOSED','REJECTED')),
 created_at timestamptz NOT NULL DEFAULT now(), verified_at timestamptz, resolved_at timestamptz,
 CHECK(verified_at IS NULL OR verified_at>=created_at), CHECK(resolved_at IS NULL OR resolved_at>=created_at),
 CHECK((status IN ('RESOLVED','CLOSED')) = (resolved_at IS NOT NULL))
);
CREATE TABLE incident_report (report_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), incident_id uuid NOT NULL REFERENCES incident ON DELETE CASCADE, reporter_id uuid NOT NULL REFERENCES "user" ON DELETE RESTRICT, report_text text NOT NULL CHECK(length(trim(report_text))>=10), evidence_url varchar(2048) CHECK(evidence_url IS NULL OR evidence_url ~ '^https?://'), latitude numeric(9,6) CHECK(latitude BETWEEN -90 AND 90), longitude numeric(9,6) CHECK(longitude BETWEEN -180 AND 180), reported_at timestamptz NOT NULL DEFAULT now(), CHECK((latitude IS NULL)=(longitude IS NULL)));
CREATE TABLE report_embedding (embedding_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid NOT NULL UNIQUE REFERENCES incident_report ON DELETE CASCADE, embedding vector(384) NOT NULL, model_name varchar(150) NOT NULL, model_version int NOT NULL CHECK(model_version>0), generated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assignment (assignment_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), incident_id uuid NOT NULL REFERENCES incident ON DELETE CASCADE, assigned_staff_id uuid NOT NULL REFERENCES "user" ON DELETE RESTRICT, assigned_by uuid NOT NULL REFERENCES "user" ON DELETE RESTRICT, assignment_status varchar(15) NOT NULL DEFAULT 'PENDING' CHECK(assignment_status IN ('PENDING','ACCEPTED','COMPLETED','CANCELLED')), assigned_at timestamptz NOT NULL DEFAULT now(), accepted_at timestamptz, completed_at timestamptz, CHECK(accepted_at IS NULL OR accepted_at>=assigned_at), CHECK(completed_at IS NULL OR completed_at>=accepted_at), CHECK((assignment_status IN ('ACCEPTED','COMPLETED'))=(accepted_at IS NOT NULL)), CHECK((assignment_status='COMPLETED')=(completed_at IS NOT NULL)));
CREATE TABLE incident_update (update_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), incident_id uuid NOT NULL REFERENCES incident ON DELETE CASCADE, author_id uuid NOT NULL REFERENCES "user" ON DELETE RESTRICT, update_message text NOT NULL CHECK(length(trim(update_message))>=3), evidence_url varchar(2048) CHECK(evidence_url IS NULL OR evidence_url ~ '^https?://'), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE status_history (history_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), incident_id uuid NOT NULL REFERENCES incident ON DELETE CASCADE, changed_by uuid NOT NULL REFERENCES "user" ON DELETE RESTRICT, old_status varchar(20), new_status varchar(20) NOT NULL, change_reason text NOT NULL, changed_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE sop_document (document_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), category_id int NOT NULL REFERENCES incident_category ON DELETE RESTRICT, document_title varchar(180) NOT NULL, source_url varchar(2048) NOT NULL CHECK(source_url ~ '^https?://'), document_version int NOT NULL CHECK(document_version>0), is_verified boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(category_id,document_title,document_version));
CREATE TABLE sop_chunk (chunk_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid NOT NULL REFERENCES sop_document ON DELETE CASCADE, chunk_content text NOT NULL CHECK(length(trim(chunk_content))>0), chunk_number int NOT NULL CHECK(chunk_number>0), embedding vector(384) NOT NULL, embedding_model varchar(150) NOT NULL, UNIQUE(document_id,chunk_number));

CREATE INDEX incident_status_priority_idx ON incident(status,priority_score DESC);
CREATE INDEX incident_location_idx ON incident(location_id);
CREATE INDEX incident_category_idx ON incident(category_id);
CREATE INDEX report_incident_idx ON incident_report(incident_id);
CREATE INDEX report_reporter_idx ON incident_report(reporter_id);
CREATE INDEX assignment_staff_idx ON assignment(assigned_staff_id,assignment_status);
CREATE UNIQUE INDEX one_active_assignment_idx ON assignment(incident_id) WHERE assignment_status IN ('PENDING','ACCEPTED');
CREATE INDEX update_incident_time_idx ON incident_update(incident_id,created_at);
CREATE INDEX history_incident_time_idx ON status_history(incident_id,changed_at);
CREATE INDEX incident_fts_idx ON incident USING gin(to_tsvector('english', title || ' ' || description));
CREATE INDEX report_vector_hnsw_idx ON report_embedding USING hnsw(embedding vector_cosine_ops);
CREATE INDEX sop_vector_hnsw_idx ON sop_chunk USING hnsw(embedding vector_cosine_ops);

CREATE FUNCTION calculate_priority(p_severity text,p_reports bigint,p_age_minutes numeric) RETURNS numeric LANGUAGE sql IMMUTABLE AS $$
 SELECT (CASE p_severity WHEN 'CRITICAL' THEN 80 WHEN 'HIGH' THEN 60 WHEN 'MEDIUM' THEN 40 ELSE 20 END + least(15,greatest(0,p_reports-1)*3) + least(5,greatest(0,p_age_minutes)/60))::numeric(8,2)
$$;
CREATE VIEW incident_dashboard AS
 SELECT i.*,l.location_name,b.building_name,c.category_name,
 (SELECT count(*) FROM incident_report r WHERE r.incident_id=i.incident_id) AS report_count,
 calculate_priority(i.severity,(SELECT count(*) FROM incident_report r WHERE r.incident_id=i.incident_id),extract(epoch FROM now()-i.created_at)/60) AS live_priority,
 i.created_at+make_interval(mins=>s.response_minutes) AS response_due_at,
 i.created_at+make_interval(mins=>s.resolution_minutes) AS resolution_due_at,
 (SELECT min(a.accepted_at) FROM assignment a WHERE a.incident_id=i.incident_id) AS first_response_at,
 CASE WHEN s.sla_policy_id IS NULL THEN 'NO_POLICY'
 WHEN i.status='REJECTED' THEN 'NOT_APPLICABLE'
 WHEN COALESCE((SELECT min(a.accepted_at) FROM assignment a WHERE a.incident_id=i.incident_id),now()) > i.created_at+make_interval(mins=>s.response_minutes)
 OR COALESCE(i.resolved_at,now()) > i.created_at+make_interval(mins=>s.resolution_minutes) THEN 'BREACHED' ELSE 'ON_TRACK' END AS sla_state
 FROM incident i JOIN location l USING(location_id) JOIN building b USING(building_id) JOIN incident_category c USING(category_id)
 LEFT JOIN sla_policy s ON s.category_id=i.category_id AND s.severity_level=i.severity;

CREATE FUNCTION enforce_status_transition() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE actor uuid; reason text;
BEGIN
 IF TG_OP='UPDATE' AND NEW.status=OLD.status THEN RETURN NEW; END IF;
 actor:=nullif(current_setting('app.actor_id',true),'')::uuid;
 reason:=coalesce(nullif(current_setting('app.change_reason',true),''),'Incident created');
 IF actor IS NULL THEN RAISE EXCEPTION 'Audit actor required'; END IF;
 IF TG_OP='INSERT' THEN
   IF NEW.status<>'REPORTED' THEN RAISE EXCEPTION 'New incidents must be REPORTED'; END IF;
 ELSE
   IF NOT ((OLD.status='REPORTED' AND NEW.status IN ('VERIFIED','REJECTED')) OR
    (OLD.status='VERIFIED' AND NEW.status IN ('ASSIGNED','REJECTED')) OR
    (OLD.status='ASSIGNED' AND NEW.status='IN_PROGRESS') OR
    (OLD.status='IN_PROGRESS' AND NEW.status='RESOLVED') OR
    (OLD.status='RESOLVED' AND NEW.status='CLOSED')) THEN RAISE EXCEPTION 'Invalid status transition: % -> %',OLD.status,NEW.status; END IF;
 END IF;
 IF NEW.status='VERIFIED' THEN NEW.verified_at:=now(); END IF;
 IF NEW.status='RESOLVED' THEN NEW.resolved_at:=now(); END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER validate_status BEFORE INSERT OR UPDATE OF status ON incident FOR EACH ROW EXECUTE FUNCTION enforce_status_transition();
CREATE FUNCTION audit_status() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status THEN
 INSERT INTO status_history(incident_id,changed_by,old_status,new_status,change_reason) VALUES(NEW.incident_id,current_setting('app.actor_id')::uuid,CASE WHEN TG_OP='INSERT' THEN NULL ELSE OLD.status END,NEW.status,coalesce(nullif(current_setting('app.change_reason',true),''),'Incident created'));
 END IF; RETURN NEW;
END $$;
CREATE TRIGGER audit_status_change AFTER INSERT OR UPDATE OF status ON incident FOR EACH ROW EXECUTE FUNCTION audit_status();
CREATE FUNCTION validate_assignment_roles() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM user_role ur JOIN role r USING(role_id) JOIN "user" u USING(user_id) WHERE ur.user_id=NEW.assigned_staff_id AND r.role_name='STAFF' AND u.is_active) THEN RAISE EXCEPTION 'Assignee must be active STAFF'; END IF;
 IF NOT EXISTS(SELECT 1 FROM user_role ur JOIN role r USING(role_id) JOIN "user" u USING(user_id) WHERE ur.user_id=NEW.assigned_by AND r.role_name='ADMIN' AND u.is_active) THEN RAISE EXCEPTION 'Assigner must be active ADMIN'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER assignment_role_guard BEFORE INSERT OR UPDATE OF assigned_staff_id,assigned_by ON assignment FOR EACH ROW EXECUTE FUNCTION validate_assignment_roles();
CREATE FUNCTION require_incident_report() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE iid uuid;
BEGIN
 iid:=CASE WHEN TG_TABLE_NAME='incident' THEN NEW.incident_id ELSE OLD.incident_id END;
 IF EXISTS(SELECT 1 FROM incident WHERE incident_id=iid) AND NOT EXISTS(SELECT 1 FROM incident_report WHERE incident_id=iid) THEN RAISE EXCEPTION 'An incident requires at least one report'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER incident_has_report AFTER INSERT ON incident DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION require_incident_report();
CREATE CONSTRAINT TRIGGER preserve_last_report AFTER DELETE OR UPDATE OF incident_id ON incident_report DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION require_incident_report();
CREATE FUNCTION require_sop_chunk() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE did uuid;
BEGIN
 did:=CASE WHEN TG_TABLE_NAME='sop_document' THEN NEW.document_id ELSE OLD.document_id END;
 IF EXISTS(SELECT 1 FROM sop_document WHERE document_id=did) AND NOT EXISTS(SELECT 1 FROM sop_chunk WHERE document_id=did) THEN RAISE EXCEPTION 'An SOP document requires at least one chunk'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER document_has_chunk AFTER INSERT ON sop_document DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION require_sop_chunk();
CREATE CONSTRAINT TRIGGER preserve_last_chunk AFTER DELETE OR UPDATE OF document_id ON sop_chunk DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION require_sop_chunk();
-- SQL ALTER example: strengthen non-blank catalogue identifiers after table creation.
ALTER TABLE building ADD CONSTRAINT building_code_nonempty CHECK(length(trim(building_code))>0);
